# -*- coding: utf-8 -*-
"""4분류 카탈로그의 단일 원본 — 카테고리 → 그룹(삼성노트식 묶음) → 항목.

여기서 02~05 md(카탈로그_생성.py)와 목업 렌더 목록(렌더.py)을 모두 만든다. 항목을 더하거나 고치면 이 파일만 고친다.
항목 필드:
  id     코드용 식별자 (--only 로 고를 때 쓴다). 파일 이름은 파일이름()이 title 에서 만든다: 목업/<분류>-<이름>.jpg
  title  이름            desc  한 줄 설명(무엇)
  why    조사 근거(01 트렌드 조사.md 의 어느 발견에서 왔나)
  spec   칸 구성 · 옵션 (속지) / 모양 · 동작 (에셋)
  online 온라인 항목만: 상태 · 알림 · 데이터 소스
  fn     목업 함수 "모듈.함수" (fn(W,H,land) 또는 fn(W,H))
"""

import re

PREFIX_KO = {"po": "일반속지", "pn": "온라인속지", "ao": "오프라인에셋", "an": "온라인에셋"}


def 파일이름(prefix, it):
    """목업 파일 줄기(확장자 제외): '<분류>-<title 에서 괄호 설명 · 특수문자를 뺀 이름>'. 예) 일반속지 코넬 노트"""
    s = re.sub(r"\s*[\(（].*?[\)）]", "", it["title"])
    s = re.sub(r"[·+,'\"“”‘’!?:;/\*<>|\[\]]", " ", s)
    s = re.sub(r"\s+", " ", s.strip()).strip(". ")
    return f"{PREFIX_KO[prefix]} {s}"


