def all_items():
    for cat in CATEGORIES:
        for grp in cat["groups"]:
            for it in grp["items"]:
                yield cat, grp, it


if __name__ == "__main__":
    n = 0
    for cat in CATEGORIES:
        c = sum(len(g["items"]) for g in cat["groups"])
        n += c
        print(f"{cat['title']}: {len(cat['groups'])}그룹 {c}항목")
    print("총", n, "항목")
